package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import com.qualcomm.robotcore.hardware.DcMotorSimple;
import com.qualcomm.robotcore.hardware.HardwareMap;

import org.firstinspires.ftc.teamcode.config.DeviceNames;

// Generated by refract-suite ftc-construct. Two motors (team 2026-10-17): the main motor runs the intake roller and
// pushes NECTAR up the ramp to the front launcher; the POLLEN feeder motor drives the 2 wheels that carry POLLEN
// under the ramp to the back launcher. Collecting, firing POLLEN and ejecting need both; firing NECTAR only the main
// motor (the back gate holds POLLEN while it runs).
public class Intake {
    // operating powers, not measurements (DECODE ran 0.8 in, -1 out); feed powers are measured (G-5)
    public static double IN_POWER = 0.8;
    public static double EJECT_POWER = 1.0;
    // set by prerequisites E-3: true if +power pushes elements out (main) / away from the back launcher (POLLEN feeder)
    public static boolean REVERSED = false;
    public static boolean POLLEN_REVERSED = false;

    private final DcMotorEx main, pollen;
    private String problem = "";

    public Intake(HardwareMap hardwareMap) {
        main = motor(hardwareMap, DeviceNames.INTAKE, REVERSED);
        pollen = motor(hardwareMap, DeviceNames.POLLEN_FEED, POLLEN_REVERSED);
    }

    private static DcMotorEx motor(HardwareMap hardwareMap, String name, boolean reversed) {
        DcMotorEx m = hardwareMap.get(DcMotorEx.class, name);
        m.setDirection(reversed ? DcMotorSimple.Direction.REVERSE : DcMotorSimple.Direction.FORWARD);
        m.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
        return m;
    }

    public void in() {
        run(IN_POWER, IN_POWER);
    }

    public void eject(double scale) {
        double p = -EJECT_POWER * Math.abs(scale);
        run(p, p);
    }

    // A shot. Each launcher that fires has its gate open, so the main motor (it pushes both lanes) only runs while
    // every firing launcher is at speed; the POLLEN feeder only needs the back one. A launcher's feed power is the
    // Feed column of its shot table; both firing = the slower of the two. True while every firing launcher is fed;
    // false (and problem() says why) when a firing launcher has no feed power yet (NaN = no table).
    public boolean fire(boolean front, boolean frontReady, double frontPower, boolean back, boolean backReady, double backPower) {
        if ((front && Double.isNaN(frontPower)) || (back && Double.isNaN(backPower)) || !(front || back)) {
            problem = front || back ? "feed power not set (G-5)" : "";
            stop();
            return false;
        }
        problem = "";
        boolean mainGo = (!front || frontReady) && (!back || backReady);
        double mainPower = !mainGo ? 0 : front && back ? Math.min(frontPower, backPower) : front ? frontPower : backPower;
        run(mainPower, back && backReady ? backPower : 0);
        return mainGo;
    }

    public String problem() {
        return problem;
    }

    // data collection (shot tuners, flywheel tuner): one launcher fed at this power, as fire() feeds it alone
    public void feedOne(boolean back, double power) {
        run(power, back ? power : 0);
    }

    public void run(double mainPower, double pollenPower) {
        main.setPower(mainPower);
        pollen.setPower(pollenPower);
    }

    public void stop() {
        run(0, 0);
    }
}
